using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings", MimeType = "application/json")]
    [Description("Returns the current application configuration.")]
    public static string GetAppSettings() =>
        """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "notifications": true
            },
            "limits": {
                "maxRequestsPerMinute": 100,
                "maxPayloadSizeMb": 10
            }
        }
        """;

    [McpServerResource(UriTemplate = "config://app/status", Name = "ServerStatus", MimeType = "application/json")]
    [Description("Returns the current server health status.")]
    public static string GetServerStatus() =>
        $$"""
        {
            "status": "healthy",
            "uptime": "{{TimeSpan.FromMilliseconds(Environment.TickCount64)}}",
            "timestamp": "{{DateTimeOffset.UtcNow:O}}"
        }
